-- GENERATED by `npm run scaffold` from extract_wp_seqs_parts.sql for SGN-NGTHCM. Edit the root template, not this file.
-- Query: Result B (parts) of the split WP-sequences extraction.
-- One row per part request, only for worksteps that have parts. Keyed by z_WORKSTEP_LINK_ID,
-- which matches the last column of extract_wp_seqs_steps.sql.
-- The WP filter sits in an EXISTS so each part request appears exactly once, even when the same
-- work order is listed more than once in wp_sequence (joining through wp_sequence would repeat the
-- part rows, and the stitcher would then multiply them by the repeated step rows).
-- Keep the WP filter in sync with extract_wp_seqs_steps.sql (station/department/windows).

SELECT 
    workstep_link.workstep_linkno_i AS z_WORKSTEP_LINK_ID,
    part_request_2.partno AS z_PART_NO,
    part_request_2.qty AS z_PART_QTY,
    part_request_2.no_pcf AS z_PART_NO_PCF
FROM part_request_2
JOIN workstep_link
       ON workstep_link.workstep_linkno_i = part_request_2.event_key
WHERE part_request_2.event_type = 'WSL'
  AND EXISTS (
      SELECT 1
      FROM wp_header
      JOIN wp_status 
             ON wp_status.wp_status_id = wp_header.wp_status
      JOIN wp_department_link
             ON wp_department_link.wpno_i = wp_header.wpno_i
      JOIN wp_sequence 
             ON wp_sequence.wpno_i = wp_header.wpno_i
      JOIN wo_header 
             ON wo_header.event_perfno_i = wp_sequence.event_perfno_i
      WHERE wo_header.event_perfno_i = workstep_link.event_perfno_i
        AND wp_header.station = 'SGN'
        AND wp_department_link.department = 'NGTHCM'
        AND (
            -- Condition 1: In Progress or Issued in the last 6 months
            (
                wp_status.name IN ('In Progress', 'Issued')
                AND wp_header.start_date <= (CURRENT_DATE - DATE '1971-12-31')
                AND wp_header.start_date >= ((CURRENT_DATE - INTERVAL '6' MONTH)::date - DATE '1971-12-31')
            )
            OR
            -- Condition 2: Closed WPs in the last 24 hours
            (
                wp_status.name = 'Closed'
                AND wp_header.end_date IS NOT NULL
                AND wp_header.end_date >= ((CURRENT_TIMESTAMP + INTERVAL '7' HOUR - INTERVAL '24' HOUR)::date - DATE '1971-12-31')
                AND ((DATE '1971-12-31' + wp_header.end_date) + (COALESCE(wp_header.end_time, 0) * INTERVAL '1 minute')) >= (CURRENT_TIMESTAMP + INTERVAL '7' HOUR - INTERVAL '24' HOUR)
            )
        )
  );
